import math
from collections.abc import Mapping
from numbers import Real


def _finite(value):
    return (isinstance(value, Real)
            and not isinstance(value, bool)
            and (not isinstance(value, float) or math.isfinite(value)))


def bucket_metrics(entries, thresholds):
    if not isinstance(thresholds, Mapping) or not thresholds:
        raise ValueError("thresholds must be a nonempty mapping")
    metric_names = list(thresholds)
    for name, value in thresholds.items():
        if not isinstance(name, str) or not name or not _finite(value):
            raise ValueError("invalid threshold")

    try:
        source_entries = list(entries)
    except TypeError as exc:
        raise ValueError("entries must be iterable") from exc

    result = {
        name: {"below": [], "at_or_above": []}
        for name in metric_names
    }
    seen_ids = set()
    for entry in source_entries:
        if not isinstance(entry, Mapping) or set(entry) != {"id", "metrics"}:
            raise ValueError("invalid entry")
        identifier = entry["id"]
        try:
            if identifier in seen_ids:
                raise ValueError("duplicate id")
            seen_ids.add(identifier)
        except TypeError as exc:
            raise ValueError("ids must be hashable") from exc
        metrics = entry["metrics"]
        if not isinstance(metrics, Mapping) or set(metrics) != set(metric_names):
            raise ValueError("metric names do not match thresholds")
        for name in metric_names:
            value = metrics[name]
            if not _finite(value):
                raise ValueError("metric values must be finite numbers")
            bucket = "at_or_above" if value >= thresholds[name] else "below"
            result[name][bucket].append(identifier)
    return result

