#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Reading {
    pub value: u128,
    pub kind: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum AggregateError {
    UnexpectedKind { expected: String, found: String },
    Overflow,
}

pub fn aggregate_readings(
    readings: &[Reading],
    expected_kind: &str,
) -> Result<Reading, AggregateError> {
    for reading in readings {
        if reading.kind != expected_kind {
            return Err(AggregateError::UnexpectedKind {
                expected: expected_kind.to_owned(),
                found: reading.kind.clone(),
            });
        }
    }

    let mut total = 0u128;
    for reading in readings {
        total = total
            .checked_add(reading.value)
            .ok_or(AggregateError::Overflow)?;
    }

    Ok(Reading {
        value: total,
        kind: expected_kind.to_owned(),
    })
}

