#[path = "solution.rs"]
mod solution;

use solution::{AggregateError, Reading};

fn successful(result: Result<Reading, AggregateError>) -> Reading {
    match result {
        Ok(reading) => reading,
        Err(_) => panic!("expected successful aggregation"),
    }
}

#[test]
fn empty_slice_produces_zero_with_an_owned_expected_kind() {
    let expected = String::from("requests");
    let result = successful(solution::aggregate_readings(&[], &expected));
    assert_eq!(result.value, 0);
    assert_eq!(result.kind, "requests");
    drop(expected);
    assert_eq!(result.kind, "requests");
}

#[test]
fn values_are_summed_without_mutating_inputs() {
    let readings = vec![
        Reading { value: 0, kind: "bytes".into() },
        Reading { value: 7, kind: "bytes".into() },
        Reading { value: 11, kind: "bytes".into() },
    ];
    let result = successful(solution::aggregate_readings(&readings, "bytes"));
    assert_eq!(result.value, 18);
    assert_eq!(result.kind, "bytes");
    assert_eq!(readings[0].value, 0);
    assert_eq!(readings[1].value, 7);
    assert_eq!(readings[2].value, 11);
    assert_eq!(readings[0].kind, "bytes");
    assert_eq!(readings[1].kind, "bytes");
    assert_eq!(readings[2].kind, "bytes");
}

#[test]
fn exact_u128_maximum_is_valid() {
    let readings = [Reading { value: u128::MAX, kind: "units".into() }];
    let result = successful(solution::aggregate_readings(&readings, "units"));
    assert_eq!(result.value, u128::MAX);
    assert_eq!(result.kind, "units");
}

#[test]
fn overflow_is_reported_instead_of_wrapping_or_saturating() {
    let readings = [
        Reading { value: u128::MAX, kind: "units".into() },
        Reading { value: 1, kind: "units".into() },
    ];
    match solution::aggregate_readings(&readings, "units") {
        Err(AggregateError::Overflow) => {}
        _ => panic!("expected Overflow"),
    }
    assert_eq!(readings[0].value, u128::MAX);
    assert_eq!(readings[1].value, 1);
}

#[test]
fn first_mismatch_is_reported_deterministically() {
    let readings = [
        Reading { value: 1, kind: "expected".into() },
        Reading { value: 2, kind: "first_bad".into() },
        Reading { value: 3, kind: "second_bad".into() },
    ];
    match solution::aggregate_readings(&readings, "expected") {
        Err(AggregateError::UnexpectedKind { expected, found }) => {
            assert_eq!(expected, "expected");
            assert_eq!(found, "first_bad");
        }
        _ => panic!("expected UnexpectedKind"),
    }
}

#[test]
fn kind_validation_takes_precedence_over_sum_overflow() {
    let readings = [
        Reading { value: u128::MAX, kind: "ok".into() },
        Reading { value: 1, kind: "ok".into() },
        Reading { value: 0, kind: "wrong".into() },
    ];
    match solution::aggregate_readings(&readings, "ok") {
        Err(AggregateError::UnexpectedKind { expected, found }) => {
            assert_eq!(expected, "ok");
            assert_eq!(found, "wrong");
        }
        _ => panic!("expected the mismatch found while inspecting all readings"),
    }
}

#[test]
fn matching_empty_kind_is_valid_and_comparison_is_exact() {
    let readings = [Reading { value: 5, kind: String::new() }];
    let result = successful(solution::aggregate_readings(&readings, ""));
    assert_eq!(result.value, 5);
    assert_eq!(result.kind, "");

    let case_sensitive = [Reading { value: 1, kind: "Kind".into() }];
    match solution::aggregate_readings(&case_sensitive, "kind") {
        Err(AggregateError::UnexpectedKind { expected, found }) => {
            assert_eq!(expected, "kind");
            assert_eq!(found, "Kind");
        }
        _ => panic!("expected exact kind comparison"),
    }
}

#[test]
fn returned_reading_is_independent_of_inputs() {
    let readings = [Reading { value: 4, kind: "count".into() }];
    let mut result = successful(solution::aggregate_readings(&readings, "count"));
    result.value = 99;
    result.kind.push_str("-changed");
    assert_eq!(readings[0].value, 4);
    assert_eq!(readings[0].kind, "count");
}

